router6.get("/accounting/summary", async (req, res) => {
  try {
    const { where: acctWhere } = resolveAccountingScope(req);
    const studentWhere = resolvePaymentStudentScope(req);
    const { academicYear, from, to } = req.query;
    const dateFrom = from && typeof from === "string" ? new Date(from) : void 0;
    const dateTo = to && typeof to === "string" ? new Date(to) : void 0;
    const payWhere = { status: "COMPLETED", student: studentWhere };
    if (dateFrom || dateTo) {
      payWhere.paidAt = {};
      if (dateFrom) payWhere.paidAt.gte = dateFrom;
      if (dateTo) payWhere.paidAt.lte = dateTo;
    }
    if (academicYear && typeof academicYear === "string") {
      payWhere.tuitionFee = { academicYear: String(academicYear), student: studentWhere };
    }
    const payments = await prisma_default.payment.findMany({
      where: payWhere,
      select: { amount: true }
    });
    const tuitionRevenue = payments.reduce((s, p) => s + p.amount, 0);
    const expWhere = { ...acctWhere };
    if (dateFrom || dateTo) {
      expWhere.expenseDate = {};
      if (dateFrom) expWhere.expenseDate.gte = dateFrom;
      if (dateTo) expWhere.expenseDate.lte = dateTo;
    }
    if (academicYear && typeof academicYear === "string") {
      expWhere.academicYear = String(academicYear);
    }
    const expenses = await prisma_default.schoolExpense.findMany({
      where: expWhere,
      select: { amount: true, category: true }
    });
    const totalExpenses = expenses.reduce((s, e) => s + e.amount, 0);
    const expensesByCategory = expenses.reduce((acc, e) => {
      acc[e.category] = (acc[e.category] || 0) + e.amount;
      return acc;
    }, {});
    const petty = await prisma_default.pettyCashMovement.findMany({
      where: {
        ...acctWhere,
        ...dateFrom || dateTo ? {
          movementDate: {
            ...dateFrom ? { gte: dateFrom } : {},
            ...dateTo ? { lte: dateTo } : {}
          }
        } : {}
      },
      select: { type: true, amount: true }
    });
    let pettyNet = 0;
    let pettyInPeriod = 0;
    let pettyOutPeriod = 0;
    for (const p of petty) {
      if (p.type === "IN") {
        pettyNet += p.amount;
        pettyInPeriod += p.amount;
      } else {
        pettyNet -= p.amount;
        pettyOutPeriod += p.amount;
      }
    }
    const allPetty = await prisma_default.pettyCashMovement.findMany({
      where: acctWhere,
      select: { type: true, amount: true }
    });
    let pettyBalance = 0;
    for (const p of allPetty) {
      pettyBalance += p.type === "IN" ? p.amount : -p.amount;
    }
    const budgetRows = academicYear && typeof academicYear === "string" ? await prisma_default.budgetLine.findMany({
      where: { academicYear: String(academicYear), ...acctWhere }
    }) : await prisma_default.budgetLine.findMany({ where: acctWhere });
    const budgetTotal = budgetRows.reduce((s, b) => s + b.budgetedAmount, 0);
    res.json({
      period: { from: dateFrom ?? null, to: dateTo ?? null, academicYear: academicYear ?? null },
      tuitionRevenue: Math.round(tuitionRevenue),
      totalExpenses: Math.round(totalExpenses),
      expensesByCategory,
      pettyCashNetPeriod: Math.round(pettyNet),
      pettyCashInPeriod: Math.round(pettyInPeriod),
      pettyCashOutPeriod: Math.round(pettyOutPeriod),
      pettyCashBalance: Math.round(pettyBalance),
      resultBeforePetty: Math.round(tuitionRevenue - totalExpenses),
      /** Synthèse type compte de résultat simplifié (hors bilan patrimonial détaillé) */
      simplifiedPL: {
        produitsEncaissementsScolarite: Math.round(tuitionRevenue),
        autresEncaissementsCaisse: Math.round(pettyInPeriod),
        totalProduits: Math.round(tuitionRevenue + pettyInPeriod),
        chargesExploitation: Math.round(totalExpenses),
        sortiesCaisse: Math.round(pettyOutPeriod),
        totalCharges: Math.round(totalExpenses + pettyOutPeriod),
        resultatNet: Math.round(tuitionRevenue + pettyInPeriod - totalExpenses - pettyOutPeriod)
      },
      budgetLines: budgetRows,
      budgetTotalPlanned: Math.round(budgetTotal)
    });
  } catch (e) {
    res.status(500).json({ error: e instanceof Error ? e.message : "Erreur serveur" });
  }
});
router6.get("/accounting/journal", async (req, res) => {
  try {
    const { where: acctWhere } = resolveAccountingScope(req);
    const studentWhere = resolvePaymentStudentScope(req);
    const { from, to, academicYear } = req.query;
    const dateFrom = from && typeof from === "string" ? new Date(from) : void 0;
    const dateTo = to && typeof to === "string" ? new Date(to) : void 0;
    const rows = [];
    const payWhere = { status: "COMPLETED", student: studentWhere };
    if (dateFrom || dateTo) {
      payWhere.paidAt = {};
      if (dateFrom) payWhere.paidAt.gte = dateFrom;
      if (dateTo) payWhere.paidAt.lte = dateTo;
    }
    if (academicYear && typeof academicYear === "string") {
      payWhere.tuitionFee = { academicYear: String(academicYear), student: studentWhere };
    }
    const pays = await prisma_default.payment.findMany({
      where: payWhere,
      include: {
        tuitionFee: { select: { period: true, academicYear: true } },
        student: { include: { user: { select: { firstName: true, lastName: true } } } }
      }
    });
    for (const p of pays) {
      const payAmount = Math.round(p.amount);
      rows.push({
        id: `pay-${p.id}`,
        date: (p.paidAt || p.createdAt).toISOString(),
        kind: "REVENUE",
        label: `Scolarit\xE9 \u2014 ${p.tuitionFee.period} (${p.tuitionFee.academicYear}) \u2014 ${p.student.user.firstName} ${p.student.user.lastName}`,
        reference: p.paymentReference,
        amount: payAmount,
        ledgerCode: TUITION_REVENUE.code,
        ledgerLabel: TUITION_REVENUE.label,
        paymentMethod: p.paymentMethod,
        debit: 0,
        credit: payAmount
      });
    }
    const expWhere = { ...acctWhere };
    if (dateFrom || dateTo) {
      expWhere.expenseDate = {};
      if (dateFrom) expWhere.expenseDate.gte = dateFrom;
      if (dateTo) expWhere.expenseDate.lte = dateTo;
    }
    if (academicYear && typeof academicYear === "string") expWhere.academicYear = String(academicYear);
    const exps = await prisma_default.schoolExpense.findMany({
      where: expWhere,
      include: { supplier: { select: { name: true } } }
    });
    for (const e of exps) {
      const L = EXPENSE_LEDGER[e.category];
      const expAmount = Math.round(e.amount);
      rows.push({
        id: `exp-${e.id}`,
        date: e.expenseDate.toISOString(),
        kind: "EXPENSE",
        label: `${e.description}${e.supplier ? ` \u2014 ${e.supplier.name}` : ""}`,
        reference: e.reference,
        amount: expAmount,
        ledgerCode: L.code,
        ledgerLabel: L.label,
        paymentMethod: e.paymentMethod,
        debit: expAmount,
        credit: 0
      });
    }
    const pcWhere = { ...acctWhere };
    if (dateFrom || dateTo) {
      pcWhere.movementDate = {};
      if (dateFrom) pcWhere.movementDate.gte = dateFrom;
      if (dateTo) pcWhere.movementDate.lte = dateTo;
    }
    const pcs = await prisma_default.pettyCashMovement.findMany({ where: pcWhere });
    for (const c of pcs) {
      const pcAmount = Math.round(c.amount);
      const isIn = c.type === "IN";
      rows.push({
        id: `pc-${c.id}`,
        date: c.movementDate.toISOString(),
        kind: isIn ? "PETTY_IN" : "PETTY_OUT",
        label: c.reason,
        reference: c.reference,
        amount: pcAmount,
        ledgerCode: PETTY_LEDGER_IN.code,
        ledgerLabel: isIn ? `${PETTY_LEDGER_IN.label} (entr\xE9e)` : `${PETTY_LEDGER_OUT.label} (sortie)`,
        paymentMethod: null,
        debit: isIn ? 0 : pcAmount,
        credit: isIn ? pcAmount : 0
      });
    }
    rows.sort((a, b) => new Date(b.date).getTime() - new Date(a.date).getTime());
    res.json(rows);
  } catch (e) {
    res.status(500).json({ error: e instanceof Error ? e.message : "Erreur serveur" });
  }
});
