        level: row.level,
        room: row.room,
        capacity: row.capacity,
        academicYear: preview.toAcademicYear,
        schoolId: source?.schoolId ?? opts.schoolId ?? void 0,
        educationSector: row.educationSector,
        trackId: row.trackId ?? void 0,
        teacherId: opts.copyTeacherAssignments ? row.teacherId ?? void 0 : void 0
