// src/utils/student-risk-ai.util.ts
function riskLevelFromScore(score) {
  if (score >= 75) return "critical";
  if (score >= 55) return "high";
  if (score >= 35) return "medium";
  return "low";
}
function computeStudentRiskScore(input) {
  const factors = [];
  if (input.average20 != null) {
    if (input.average20 < 8) {
      factors.push({
        code: "AVG_CRITICAL",
        label: "Moyenne critique",
        points: 35,
        detail: `${input.average20.toFixed(1)}/20`
      });
    } else if (input.average20 < 10) {
      factors.push({
        code: "AVG_LOW",
        label: "Moyenne insuffisante",
        points: 25,
        detail: `${input.average20.toFixed(1)}/20`
      });
    } else if (input.average20 < 12) {
      factors.push({
        code: "AVG_WATCH",
        label: "Moyenne \xE0 surveiller",
        points: 12,
        detail: `${input.average20.toFixed(1)}/20`
      });
    }
  }
  if (input.unjustifiedAbsences >= 8) {
    factors.push({
      code: "ABS_HIGH",
      label: "Absences non justifi\xE9es \xE9lev\xE9es",
      points: 30,
      detail: `${input.unjustifiedAbsences} absences`
    });
  } else if (input.unjustifiedAbsences > 5) {
    factors.push({
      code: "ABS_MED",
      label: "Absences non justifi\xE9es",
      points: 20,
      detail: `${input.unjustifiedAbsences} absences`
    });
  } else if (input.unjustifiedAbsences >= 3) {
    factors.push({
      code: "ABS_LOW",
      label: "Absences \xE9mergentes",
      points: 10,
      detail: `${input.unjustifiedAbsences} absences`
    });
  }
  if (input.lateCount >= 6) {
    factors.push({
      code: "LATE_HIGH",
      label: "Retards fr\xE9quents",
      points: 15,
      detail: `${input.lateCount} retards`
    });
  } else if (input.lateCount >= 3) {
    factors.push({
      code: "LATE_MED",
      label: "Retards",
      points: 8,
      detail: `${input.lateCount} retards`
    });
  }
  if (input.unpaidAmount >= 1e5) {
    factors.push({
      code: "FEE_HIGH",
      label: "Impay\xE9s \xE9lev\xE9s",
      points: 15,
      detail: `${Math.round(input.unpaidAmount).toLocaleString("fr-FR")} FCFA`
    });
  } else if (input.unpaidAmount >= 3e4) {
    factors.push({
      code: "FEE_MED",
      label: "Impay\xE9s",
      points: 8,
      detail: `${Math.round(input.unpaidAmount).toLocaleString("fr-FR")} FCFA`
    });
  }
  if (input.assignmentMissingRate != null && input.assignmentMissingRate >= 0.4) {
    factors.push({
      code: "HW_LOW",
      label: "Devoirs non rendus",
      points: 12,
      detail: `${Math.round(input.assignmentMissingRate * 100)} % manquants`
    });
  }
  const score = Math.min(
    100,
    factors.reduce((s, f) => s + f.points, 0)
  );
  return {
    studentId: input.studentId,
    score,
    level: riskLevelFromScore(score),
    factors,
    average20: input.average20,
    unjustifiedAbsences: input.unjustifiedAbsences,
    lateCount: input.lateCount,
    unpaidAmount: input.unpaidAmount
  };
}
function buildJitsiMeetingUrl(sessionId, title) {
  const base = (process.env.JITSI_BASE_URL || "https://meet.jit.si").replace(/\/$/, "");
  const slug = `ecole-${sessionId.slice(-8)}-${(title || "cours").toLowerCase().normalize("NFD").replace(/[\u0300-\u036f]/g, "").replace(/[^a-z0-9]+/g, "-").replace(/^-|-$/g, "").slice(0, 24)}`;
  return `${base}/${slug}`;
}

// src/utils/payment-overpay.util.ts
async function getTuitionFeePaymentTotals(db, tuitionFeeId) {
  const fee = await db.tuitionFee.findUnique({
    where: { id: tuitionFeeId },
    select: { amount: true }
  });
  if (!fee) {
    throw Object.assign(new Error("Ligne de frais introuvable"), { status: 404 });
  }
  const completed = await db.payment.findMany({
    where: { tuitionFeeId, status: "COMPLETED" },
    select: { amount: true }
  });
  const totalPaid = completed.reduce((s, p) => s + p.amount, 0);
  const amountDue = Math.round(fee.amount);
  const remaining = Math.max(0, amountDue - Math.round(totalPaid));
  return { totalPaid, remaining, amountDue };
}
async function assertPaymentWithinRemaining(db, tuitionFeeId, payAmount) {
  const amount = Math.round(Number(payAmount));
  if (!Number.isFinite(amount) || amount <= 0) {
    throw Object.assign(new Error("Montant invalide"), { status: 400 });
  }
  const { remaining } = await getTuitionFeePaymentTotals(db, tuitionFeeId);
  if (remaining <= 0) {
    throw Object.assign(new Error("Cette ligne est d\xE9j\xE0 sold\xE9e"), { status: 400 });
  }
  if (amount > remaining) {
    throw Object.assign(new Error(`Montant max : ${remaining} FCFA`), { status: 400 });
  }
  return { remaining };
}

