async function authorizeAdminOrStaffFinance(req, res, next) {
  const user = req.user;
  if (!user) {
    res.status(401).json({ error: "Non authentifi\xE9" });
    return;
  }
  const role = user.role;
  if (role === "ADMIN" || role === "SUPER_ADMIN") {
    next();
    return;
  }
  if (role !== "STAFF") {
    res.status(403).json({ error: "Acc\xE8s r\xE9serv\xE9 \xE0 l\u2019administration ou au personnel autoris\xE9." });
    return;
  }
  const path11 = req.path || "/";
  const method = req.method.toUpperCase();
  if (!isStaffModuleAdminPath(path11, method)) {
    res.status(403).json({ error: "Cette action est r\xE9serv\xE9e aux administrateurs." });
    return;
  }
  try {
    const ctx = await getStaffMemberModuleContext(user.id);
    if (!ctx) {
      res.status(403).json({ error: "Profil personnel introuvable." });
      return;
    }
    if (staffSecretaryBlocksDestructiveDelete(path11, method, ctx.staff.supportKind)) {
      res.status(403).json({
        error: "La suppression d\u2019\xE9l\xE8ves ou de classes est r\xE9serv\xE9e aux administrateurs. Contactez un administrateur si n\xE9cessaire."
      });
      return;
    }
    if (staffModuleAdminPathAllowed(ctx.visibleModules, path11, method, ctx.staff.supportKind)) {
      next();
      return;
    }
    res.status(403).json({
      error: "Ce module n\u2019est pas activ\xE9 pour votre compte. Contactez l\u2019administration."
    });
  } catch {
    res.status(500).json({ error: "Erreur de v\xE9rification des droits." });
  }
}

