router33.delete("/users/:id", async (req, res) => {
  try {
    const user = await prisma_default.user.findUnique({
      where: { id: req.params.id }
    });
    if (!user) {
      return res.status(404).json({ error: "Utilisateur non trouv\xE9" });
    }
    if (user.id === req.user.id) {
      return res.status(400).json({ error: "Vous ne pouvez pas supprimer votre propre compte" });
    }
    await prisma_default.$transaction(async (tx) => {
      await tx.passwordResetToken.deleteMany({ where: { userId: user.id } });
      await tx.pushSubscription.deleteMany({ where: { userId: user.id } });
      await tx.schoolMember.deleteMany({ where: { userId: user.id } });
      await tx.user.update({
        where: { id: req.params.id },
        data: {
          email: `deleted-user-${user.id}-${Date.now()}@deleted.local`,
          firstName: "Utilisateur",
          lastName: "supprim\xE9",
          phone: null,
          avatar: null,
          isActive: false
        }
      });
    });
    res.status(204).send();
  } catch (error) {
    console.error(`Erreur lors de la suppression de l'utilisateur ${req.params.id}:`, error);
    res.status(500).json({ error: error.message });
  }
});
