router33.get("/pedagogical/students-at-risk", async (req, res) => {
  try {
    const { classId } = req.query;
    const students = await prisma_default.student.findMany({
      where: classId ? { classId } : { isActive: true },
      include: {
        user: {
          select: {
            firstName: true,
            lastName: true,
            email: true
          }
        },
        class: {
          select: {
            name: true,
            level: true
          }
        },
        grades: {
          include: {
            course: true
          }
        },
        absences: true,
        tuitionFees: {
          where: { isPaid: false },
          include: {
            payments: { where: { status: "COMPLETED" }, select: { amount: true } }
          }
        },
        assignments: true
      }
    });
    const atRiskStudents = students.map((student) => {
      const grades = student.grades || [];
      const totalScore = grades.reduce((sum, g) => sum + g.score / g.maxScore * 20 * g.coefficient, 0);
      const totalCoefficient = grades.reduce((sum, g) => sum + g.coefficient, 0);
      const average = totalCoefficient > 0 ? totalScore / totalCoefficient : null;
      const unexcusedAbsences = student.absences?.filter((a) => !a.excused && a.status === "ABSENT").length || 0;
      const lateCount = student.absences?.filter((a) => a.status === "LATE").length || 0;
      const unpaidAmount = (student.tuitionFees || []).reduce((sum, fee) => {
        const paid = fee.payments.reduce((s, p) => s + p.amount, 0);
        return sum + Math.max(0, fee.amount - paid);
      }, 0);
      const assignments = student.assignments || [];
      const missingRate = assignments.length > 0 ? assignments.filter((a) => !a.submitted).length / assignments.length : null;
      const ai = computeStudentRiskScore({
        studentId: student.id,
        average20: average,
        unjustifiedAbsences: unexcusedAbsences,
        lateCount,
        unpaidAmount,
        assignmentMissingRate: missingRate
      });
      return {
        studentId: student.studentId,
        id: student.id,
        firstName: student.user.firstName,
        lastName: student.user.lastName,
        email: student.user.email,
        class: student.class?.name || "Non assign\xE9",
        average: average ?? 0,
        unexcusedAbsences,
        lateCount,
        unpaidAmount: Math.round(unpaidAmount * 100) / 100,
        totalGrades: grades.length,
        riskLevel: ai.level === "critical" ? "high" : ai.level,
        aiScore: ai.score,
        aiLevel: ai.level,
        aiFactors: ai.factors
      };
    }).filter((s) => s.aiLevel !== "low").sort((a, b) => b.aiScore - a.aiScore);
    res.json(atRiskStudents);
  } catch (error) {
    res.status(500).json({ error: error.message });
  }
});
