router33.patch("/security/2fa/users/:userId", async (req, res) => {
  try {
    const { enabled } = req.body;
    if (typeof enabled !== "boolean") {
      return res.status(400).json({ error: "enabled doit \xEAtre bool\xE9en" });
    }
    const user = await prisma_default.user.findUnique({ where: { id: req.params.userId } });
    if (!user) return res.status(404).json({ error: "Utilisateur introuvable" });
    if (enabled) {
      return res.status(400).json({
        error: "Activation admin directe non autoris\xE9e. L'utilisateur doit configurer 2FA via son compte."
      });
    }
    await prisma_default.userTwoFactorSettings.updateMany({
      where: { userId: user.id },
      data: { enabled: false }
    });
    await prisma_default.securityEvent.create({
      data: {
        userId: req.user?.id || null,
        type: "two_factor_disabled_by_admin",
        description: `2FA d\xE9sactiv\xE9e pour ${user.email}`,
        ipAddress: req.ip,
        userAgent: req.get("user-agent"),
        severity: "warning"
      }
    });
    res.json({ ok: true, enabled: false });
  } catch (error) {
    console.error("PATCH /security/2fa/users/:userId:", error);
    res.status(500).json({ error: error.message || "Erreur serveur" });
  }
});
