router36.get("/children/:studentId/tuition-fees", async (req, res) => {
  try {
    const { studentId } = req.params;
    const parent = await prisma_default.parent.findFirst({
      where: {
        userId: req.user.id
      },
      include: {
        students: {
          where: {
            studentId
          }
        }
      }
    });
    if (!parent || parent.students.length === 0) {
      return res.status(403).json({ error: "Acc\xE8s refus\xE9" });
    }
    const tuitionFees = await prisma_default.tuitionFee.findMany({
      where: {
        studentId
      },
      include: {
        payments: {
          orderBy: {
            createdAt: "desc"
          }
        }
      },
      orderBy: {
        dueDate: "asc"
      }
    });
    const feesWithPaymentInfo = tuitionFees.map((fee) => {
      const completedPayments = fee.payments.filter((p) => p.status === "COMPLETED");
      const totalPaid = completedPayments.reduce((sum, p) => sum + p.amount, 0);
      const remainingAmount = fee.amount - totalPaid;
      return {
        ...fee,
        totalPaid,
        remainingAmount: Math.max(0, remainingAmount),
        paymentProgress: fee.amount > 0 ? totalPaid / fee.amount * 100 : 0
      };
    });
    res.json(feesWithPaymentInfo);
  } catch (error) {
    console.error("Erreur lors de la r\xE9cup\xE9ration des frais de scolarit\xE9:", error);
    res.status(500).json({
      error: error.message || "Erreur serveur",
      details: process.env.NODE_ENV === "development" ? error.stack : void 0
    });
  }
});
router36.post("/children/:studentId/payments", async (req, res) => {
  try {
    const { studentId } = req.params;
    const { tuitionFeeId, paymentMethod, amount, phoneNumber, operator, transactionCode, accountNumber, reference } = req.body;
    if (!tuitionFeeId || !paymentMethod || !amount) {
      return res.status(400).json({ error: "tuitionFeeId, paymentMethod et amount sont requis" });
    }
    if (paymentMethod === "MOBILE_MONEY") {
      if (!phoneNumber) {
        return res.status(400).json({ error: "Le num\xE9ro de t\xE9l\xE9phone est requis pour Mobile Money" });
      }
      const countryCode = getPaymentDefaultCountryCode();
      if (!isValidMobileMoneyPhone(String(phoneNumber), countryCode)) {
        return res.status(400).json({
          error: `Format de num\xE9ro de t\xE9l\xE9phone invalide. Utilisez le format: ${mobileMoneyPhoneFormatHint(countryCode)}`
        });
      }
    }
    if (paymentMethod === "BANK_TRANSFER") {
      if (!accountNumber || !String(accountNumber).trim()) {
        return res.status(400).json({ error: "Le num\xE9ro de compte est requis pour un virement" });
      }
    }
    const parent = await prisma_default.parent.findFirst({
      where: {
        userId: req.user.id
      },
      include: {
        students: {
          where: {
            studentId
          }
        }
      }
    });
    if (!parent || parent.students.length === 0) {
      return res.status(403).json({ error: "Acc\xE8s refus\xE9" });
    }
    const tuitionFee = await prisma_default.tuitionFee.findFirst({
      where: {
        id: tuitionFeeId,
        studentId
      }
    });
    if (!tuitionFee) {
      return res.status(404).json({ error: "Frais de scolarit\xE9 non trouv\xE9" });
    }
    const completedPayments = await prisma_default.payment.findMany({
      where: {
        tuitionFeeId,
        status: "COMPLETED"
      }
    });
    const totalPaid = completedPayments.reduce((sum, p) => sum + p.amount, 0);
    const remainingAmount = tuitionFee.amount - totalPaid;
    if (remainingAmount <= 0) {
      return res.status(400).json({ error: "Ce frais a d\xE9j\xE0 \xE9t\xE9 enti\xE8rement pay\xE9" });
    }
    const paymentAmount = parseFloat(amount);
    if (paymentAmount <= 0) {
      return res.status(400).json({ error: "Le montant doit \xEAtre sup\xE9rieur \xE0 0" });
    }
    if (paymentAmount > remainingAmount) {
      return res.status(400).json({
        error: `Le montant ne peut pas d\xE9passer le montant restant (${remainingAmount.toFixed(0)} FCFA)`
      });
    }
    const paymentReference = `PAY-${Date.now()}-${Math.random().toString(36).substr(2, 9).toUpperCase()}`;
    let paymentNotes = "";
    if (paymentMethod === "MOBILE_MONEY") {
      paymentNotes = `Mobile Money - T\xE9l\xE9phone: ${phoneNumber}${operator ? `, Op\xE9rateur: ${operator}` : ""}${transactionCode ? `, Code: ${transactionCode}` : ""}`;
    } else if (paymentMethod === "CARD") {
      paymentNotes = "Carte bancaire \u2014 en attente de confirmation prestataire (webhook) ou validation manuelle";
    } else if (paymentMethod === "BANK_TRANSFER") {
      paymentNotes = `Virement \u2014 Compte: ${String(accountNumber).trim()}${reference ? `, R\xE9f. virement: ${String(reference).trim()}` : ""} \u2014 en attente de validation par l'\xE9conome apr\xE8s r\xE9ception`;
    } else if (paymentMethod === "CASH") {
      paymentNotes = "Esp\xE8ces \u2014 d\xE9claration en ligne en attente de validation par l'\xE9conome apr\xE8s d\xE9p\xF4t \xE0 l'administration";
    }
    const payment = await prisma_default.payment.create({
      data: {
        tuitionFeeId,
        studentId,
        payerId: req.user.id,
        payerRole: "PARENT",
        amount: paymentAmount,
        paymentMethod,
        status: "PENDING",
        paymentReference,
        notes: paymentNotes || void 0
      },
      include: {
        tuitionFee: true,
        student: {
          include: {
            user: {
              select: {
                firstName: true,
                lastName: true,
                email: true
              }
            }
          }
        }
      }
    });
    if (paymentMethod === "CASH" || paymentMethod === "BANK_TRANSFER") {
      await notifyStaffOfPendingCashPayment({
        paymentId: payment.id,
        amount: payment.amount,
        paymentReference: payment.paymentReference,
        studentFirstName: payment.student.user.firstName,
        studentLastName: payment.student.user.lastName,
        period: payment.tuitionFee.period,
        academicYear: payment.tuitionFee.academicYear,
        payerRole: "PARENT",
        paymentMethod
      }).catch((err) => console.error("notifyStaffOfPendingCashPayment:", err));
      void notifyParentCashPaymentSubmitted(payment.id).catch(
        (err) => console.error("notifyParentCashPaymentSubmitted:", err)
      );
    }
    let onlinePayment = payment;
    if (paymentMethod === "MOBILE_MONEY" || paymentMethod === "CARD") {
      const frontend = (process.env.FRONTEND_URL || "http://localhost:3000").split(",")[0]?.trim();
      const { payment: checkoutPayment, checkout } = await attachOnlineCheckout(prisma_default, payment.id, {
        method: paymentMethod,
        phoneNumber,
        operator,
        customerEmail: req.user?.email,
        customerName: req.user?.email ?? "",
        returnUrl: `${frontend}/parent?tab=payments`,
        cancelUrl: `${frontend}/parent?tab=payments`
      });
      onlinePayment = {
        ...payment,
        checkoutUrl: checkoutPayment.checkoutUrl,
        paymentProvider: checkoutPayment.paymentProvider,
        transactionId: checkoutPayment.transactionId,
        notes: checkoutPayment.notes
      };
      if (phoneNumber) {
        void notifyParentWhatsApp(
          phoneNumber,
          "Paiement initi\xE9",
          `R\xE9f. ${payment.paymentReference} \u2014 ${paymentAmount.toLocaleString("fr-FR")} FCFA. ${checkout.checkoutUrl ? `Ouvrez : ${checkout.checkoutUrl}` : checkout.ussdHint || "Validez sur votre t\xE9l\xE9phone. Le re\xE7u arrivera automatiquement."}`
        ).catch((e) => console.error("whatsapp payment:", e));
      }
      return res.status(201).json({
        payment: onlinePayment,
        paymentUrl: checkout.checkoutUrl || `/payment/process/${payment.id}`,
        checkoutUrl: checkout.checkoutUrl || null,
        provider: checkout.provider,
        mode: checkout.mode,
        ussdHint: checkout.ussdHint || null,
        message: checkout.message
      });
    }
    res.status(201).json({
      payment: onlinePayment,
      paymentUrl: onlinePayment.checkoutUrl || `/payment/process/${payment.id}`,
      checkoutUrl: onlinePayment.checkoutUrl || null,
      provider: onlinePayment.paymentProvider || null,
      message: "Paiement initi\xE9 avec succ\xE8s"
    });
  } catch (error) {
    console.error("Erreur lors de la cr\xE9ation du paiement:", error);
    res.status(500).json({
      error: error.message || "Erreur serveur",
      details: process.env.NODE_ENV === "development" ? error.stack : void 0
    });
  }
});
