function parseUserAgent(userAgent) {
  const ua = (userAgent || "").trim();
  if (!ua) {
    return { deviceType: "unknown", browser: "Inconnu", os: "Inconnu" };
  }
  const lower = ua.toLowerCase();
  let deviceType = "desktop";
  if (/bot|crawler|spider|slurp|bingpreview|facebookexternalhit/i.test(ua)) {
    deviceType = "bot";
  } else if (/ipad|tablet|kindle|playbook|silk|(android(?!.*mobile))/i.test(ua)) {
    deviceType = "tablet";
  } else if (/mobi|iphone|ipod|android.*mobile|windows phone|opera mini/i.test(ua)) {
    deviceType = "mobile";
  }
  let browser = "Autre";
  if (/edg\//i.test(ua)) browser = "Edge";
  else if (/opr\/|opera/i.test(ua)) browser = "Opera";
  else if (/chrome|crios/i.test(ua) && !/edg\//i.test(ua)) browser = "Chrome";
  else if (/firefox|fxios/i.test(ua)) browser = "Firefox";
  else if (/safari/i.test(ua) && !/chrome|crios|android/i.test(ua)) browser = "Safari";
  else if (/msie|trident/i.test(ua)) browser = "Internet Explorer";
  let os2 = "Autre";
  if (/windows nt/i.test(ua)) os2 = "Windows";
  else if (/android/i.test(ua)) os2 = "Android";
  else if (/iphone|ipad|ipod/i.test(ua)) os2 = "iOS";
  else if (/mac os x|macintosh/i.test(ua)) os2 = "macOS";
  else if (/linux/i.test(ua)) os2 = "Linux";
  else if (/cros/i.test(ua)) os2 = "Chrome OS";
  void lower;
  return { deviceType, browser, os: os2 };
}

